"""Generate the QET Mobile industrial parts catalogue. References are generated patterns, not verified OEM part numbers."""
import os, json
ROOT=os.path.join(os.path.dirname(__file__),'app','src','main','assets','parts')
SPECS=[{'catfa': 'کلیدهای محافظ', 'caten': 'Protective switches', 'count': 1100, 'families': ['MCB', 'MCCB', 'RCD', 'RCBO'], 'makers': ['Schneider Electric', 'ABB', 'Siemens', 'Eaton', 'LS Electric'], 'ratings': [6, 10, 16, 20, 25, 32, 40, 50, 63, 80, 100, 125, 160, 250, 400, 630, 800], 'poles': [1, 2, 3, 4]}, {'catfa': 'کنتاکتور و رله', 'caten': 'Contactors and relays', 'count': 1000, 'families': ['Contactor', 'Control relay', 'Thermal overload', 'Electronic overload'], 'makers': ['Schneider Electric', 'ABB', 'Siemens', 'Eaton', 'Omron', 'Finder'], 'ratings': [9, 12, 18, 25, 32, 40, 50, 65, 80, 100, 150, 185, 225, 400, 800], 'poles': [1, 2, 3, 4]}, {'catfa': 'موتورها', 'caten': 'Motors', 'count': 900, 'families': ['AC induction', 'Synchronous', 'DC motor', 'Servo', 'Stepper'], 'makers': ['Siemens', 'ABB', 'WEG', 'SEW-Eurodrive', 'Mitsubishi Electric', 'Schneider Electric'], 'ratings': [0.18, 0.37, 0.55, 0.75, 1.1, 1.5, 2.2, 3, 4, 5.5, 7.5, 11, 15, 22, 30, 45, 75, 110, 160], 'poles': [2, 4, 6, 8]}, {'catfa': 'سنسورها', 'caten': 'Sensors', 'count': 900, 'families': ['Inductive', 'Capacitive', 'Photoelectric', 'Pressure', 'Temperature', 'Level', 'Encoder'], 'makers': ['SICK', 'Omron', 'ifm', 'Pepperl+Fuchs', 'Balluff', 'Turck'], 'ratings': [5, 10, 12, 18, 24, 30, 50, 100, 250, 500, 1000, 2000], 'poles': [2, 3, 4]}, {'catfa': 'شاسی و فرمان', 'caten': 'Operator controls', 'count': 800, 'families': ['Pushbutton', 'Selector switch', 'Pilot light', 'Emergency stop'], 'makers': ['Schneider Electric', 'Siemens', 'ABB', 'Eaton', 'Omron', 'Lovato'], 'ratings': [1, 2, 3, 4, 5, 6, 10], 'poles': [1, 2, 3, 4]}, {'catfa': 'فیوز و سکسیونر', 'caten': 'Fuses and disconnectors', 'count': 700, 'families': ['Fuse', 'Fuse holder', 'Isolator', 'Load break switch'], 'makers': ['Schneider Electric', 'ABB', 'Siemens', 'Eaton', 'Mersen', 'Socomec'], 'ratings': [2, 4, 6, 10, 16, 20, 32, 40, 63, 80, 100, 125, 160, 250, 400, 630], 'poles': [1, 2, 3, 4]}, {'catfa': 'ترانس و منابع تغذیه', 'caten': 'Transformers and power supplies', 'count': 600, 'families': ['Control transformer', 'Power transformer', 'AC/DC power supply', 'DC/DC converter'], 'makers': ['Siemens', 'Phoenix Contact', 'Mean Well', 'Schneider Electric', 'ABB', 'Weidmuller'], 'ratings': [12, 24, 48, 60, 100, 150, 250, 400, 630, 1000, 1500, 2000], 'poles': [1, 2, 3]}, {'catfa': 'درایو و PLC', 'caten': 'Drives and PLC modules', 'count': 700, 'families': ['VFD', 'Soft starter', 'PLC DI', 'PLC DO', 'PLC AI', 'PLC AO'], 'makers': ['Siemens', 'ABB', 'Schneider Electric', 'Rockwell Automation', 'Mitsubishi Electric', 'Danfoss'], 'ratings': [4, 6, 8, 12, 16, 24, 32, 48, 64, 100, 150, 200], 'poles': [1, 2, 3, 4]}, {'catfa': 'ترمینال و اتصالات', 'caten': 'Terminals and connectors', 'count': 600, 'families': ['Terminal block', 'Connector', 'Cable gland', 'DIN rail', 'Terminal strip'], 'makers': ['Phoenix Contact', 'Weidmuller', 'WAGO', 'ABB', 'TE Connectivity', 'Harting'], 'ratings': [2, 4, 6, 10, 16, 25, 35, 50, 70, 95, 120, 150], 'poles': [1, 2, 3, 4, 5, 6, 8, 10, 12]}, {'catfa': 'قطعات الکترونیک', 'caten': 'Electronic components', 'count': 800, 'families': ['Resistor', 'Capacitor', 'Inductor', 'Diode', 'Transistor', 'Thyristor', 'IC'], 'makers': ['Vishay', 'Panasonic', 'Murata', 'STMicroelectronics', 'Texas Instruments', 'Infineon'], 'ratings': [0.1, 0.25, 0.5, 1, 2, 5, 10, 16, 25, 50, 100, 250, 400, 630], 'poles': [1, 2, 3]}, {'catfa': 'اندازه\u200cگیری و حفاظت', 'caten': 'Measurement and protection', 'count': 500, 'families': ['Meter', 'Protection relay', 'Timer', 'Counter'], 'makers': ['Siemens', 'Schneider Electric', 'ABB', 'Omron', 'Eaton', 'Carlo Gavazzi'], 'ratings': [1, 5, 10, 16, 25, 40, 63, 100, 250, 400, 600], 'poles': [1, 2, 3, 4]}, {'catfa': 'پنوماتیک و هیدرولیک', 'caten': 'Pneumatics and hydraulics', 'count': 400, 'families': ['Solenoid valve', 'Pneumatic cylinder', 'Hydraulic actuator', 'Pressure regulator'], 'makers': ['Festo', 'SMC', 'Parker', 'Bosch Rexroth', 'Norgren', 'Aventics'], 'ratings': [2, 4, 6, 8, 10, 12, 16, 20, 25, 32, 40, 50, 63, 80, 100], 'poles': [1, 2, 3, 4]}]
FA={'MCB': 'کلید مینیاتوری', 'MCCB': 'کلید اتوماتیک کامپکت', 'RCD': 'کلید جریان باقیمانده', 'RCBO': 'کلید ترکیبی', 'Contactor': 'کنتاکتور', 'Control relay': 'رله فرمان', 'Thermal overload': 'رله اضافه\u200cبار حرارتی', 'Electronic overload': 'رله اضافه\u200cبار الکترونیکی', 'AC induction': 'موتور القایی AC', 'Synchronous': 'موتور سنکرون', 'DC motor': 'موتور DC', 'Servo': 'سرووموتور', 'Stepper': 'استپرموتور', 'Inductive': 'سنسور القایی', 'Capacitive': 'سنسور خازنی', 'Photoelectric': 'سنسور نوری', 'Pressure': 'سنسور فشار', 'Temperature': 'سنسور دما', 'Level': 'سنسور سطح', 'Encoder': 'انکودر', 'Pushbutton': 'شاسی', 'Selector switch': 'سلکتور', 'Pilot light': 'چراغ سیگنال', 'Emergency stop': 'استاپ اضطراری', 'Fuse': 'فیوز', 'Fuse holder': 'پایه فیوز', 'Isolator': 'سکسیونر', 'Load break switch': 'کلید بار', 'Control transformer': 'ترانس کنترل', 'Power transformer': 'ترانس قدرت', 'AC/DC power supply': 'منبع تغذیه AC/DC', 'DC/DC converter': 'مبدل DC/DC', 'VFD': 'درایو فرکانس متغیر', 'Soft starter': 'سافت\u200cاستارتر', 'PLC DI': 'ماژول ورودی دیجیتال PLC', 'PLC DO': 'ماژول خروجی دیجیتال PLC', 'PLC AI': 'ماژول ورودی آنالوگ PLC', 'PLC AO': 'ماژول خروجی آنالوگ PLC', 'Terminal block': 'ترمینال بلوک', 'Connector': 'کانکتور', 'Cable gland': 'گلند کابل', 'DIN rail': 'ریل DIN', 'Terminal strip': 'ترمینال ردیفی', 'Resistor': 'مقاومت', 'Capacitor': 'خازن', 'Inductor': 'سلف', 'Diode': 'دیود', 'Transistor': 'ترانزیستور', 'Thyristor': 'تریستور', 'IC': 'مدار مجتمع', 'Meter': 'ابزار اندازه\u200cگیری', 'Protection relay': 'رله حفاظتی', 'Timer': 'تایمر', 'Counter': 'کانتر', 'Solenoid valve': 'شیر برقی', 'Pneumatic cylinder': 'سیلندر پنوماتیک', 'Hydraulic actuator': 'عملگر هیدرولیک', 'Pressure regulator': 'رگلاتور فشار'}
VOLTS=[12,24,48,110,120,220,230,380,400,415,440,480,500,690]
SYMBOLS=['breaker','contactor','motor','sensor','operator','fuse','transformer','module','terminal','electronic','meter','valve']
os.makedirs(ROOT,exist_ok=True)
for ci,s in enumerate(SPECS,1):
    rows=[]
    for j in range(s['count']):
        typ=s['families'][j%len(s['families'])]
        maker=s['makers'][(j//len(s['families']))%len(s['makers'])]
        rating=s['ratings'][(j//(len(s['families'])*len(s['makers'])))%len(s['ratings'])]
        poles=s['poles'][(j//(len(s['families'])*len(s['makers'])*len(s['ratings'])))%len(s['poles'])]
        voltage=VOLTS[(j*7+ci*3)%len(VOLTS)]
        ref=f'GEN-{ci:02d}-{j+1:04d}'
        fa=FA[typ]
        namefa=f'{fa} {rating}{"A" if ci not in (2,3,4,7,8,9,11,12) else ""} - {voltage}V - {poles}P'
        nameen=f'{typ} {rating} {"A" if ci not in (3,9) else "unit"} {voltage}V {poles}P'
        if ci==3: namefa=f'{fa} {rating}kW - {voltage}V - {poles} pole'; nameen=f'{typ} {rating}kW {voltage}V {poles} pole'
        if ci==9: namefa=f'{fa} {rating}Ω / {voltage}V'; nameen=f'{typ} {rating} ohm / {voltage}V'
        terms=max(2,poles*2 if ci in (1,2,6) else (3 if ci in (3,7,8) else 2))
        terms=min(terms,12)
        spec=f'Type={typ}; Rating={rating}; Voltage={voltage} V; Poles={poles}; Terminals={terms}'
        rows.append([f'qet-industrial-{ci:02d}-{j+1:04d}',namefa,nameen,s['catfa'],typ,maker,ref,str(rating),str(voltage),str(poles),SYMBOLS[ci-1],terms,spec])
    with open(os.path.join(ROOT,f'cat_{ci:02d}.js'),'w',encoding='utf-8') as f:
        f.write("window.QET_PARTS=window.QET_PARTS||{};window.QET_PARTS['%02d']=%s;"%(ci,json.dumps(rows,ensure_ascii=False,separators=(',',':'))))
print('Generated',sum(x['count'] for x in SPECS),'parts in 12 category files')
